def get(self, key: str, cast: typing.Callable[[typing.Any], typing.Any] | None = None, default: typing.Any = undefined) -> typing.Any:
    key_with_prefix = self.env_prefix + key
    if key_with_prefix in self.environ:
        value = self.environ[key_with_prefix]
        return self._perform_cast(key_with_prefix, value, cast)
    if key_with_prefix in self.file_values:
        value = self.file_values[key_with_prefix]
        return self._perform_cast(key_with_prefix, value, cast)
    if default is not undefined:
        return self._perform_cast(key_with_prefix, default, cast)
    raise KeyError(f"Config '{key_with_prefix}' is missing, and has no default.")
